import org.springframework.data.mongodb.core.aggregation.*;
import java.util.List;

public List<OrderWithCustomer> findOrdersWithCustomers() {

    // Stage 1: filter to only SHIPPED orders
    MatchOperation match = Aggregation.match(
        Criteria.where("status").is("SHIPPED")
    );

    // Stage 2: join with the 'customers' collection
    LookupOperation lookup = LookupOperation.newLookup()
        .from("customers")          // foreign collection
        .localField("customerId")   // field in 'orders'
        .foreignField("_id")        // field in 'customers'
        .as("customerDetails");     // output array field name

    // Stage 3: unwind the array produced by $lookup (optional if 1-to-1)
    UnwindOperation unwind = Aggregation.unwind("customerDetails", true); // preserve nulls

    // Stage 4: reshape the output
    ProjectionOperation project = Aggregation.project()
        .and("_id").as("orderId")
        .and("totalAmount").as("total")
        .and("customerDetails.name").as("customerName")
        .and("customerDetails.email").as("customerEmail");

    Aggregation pipeline = Aggregation.newAggregation(match, lookup, unwind, project);

    return mongoTemplate
        .aggregate(pipeline, "orders", OrderWithCustomer.class)
        .getMappedResults();
}

