import com.mongodb.client.MongoCollection;
import com.mongodb.client.AggregateIterable;
import org.bson.Document;
import java.util.Arrays;
import java.util.List;

// Useful when the Spring Aggregation builder doesn't expose a specific operator
public List<Document> rawAggregation(MongoCollection<Document> collection) {

    List<Document> pipeline = Arrays.asList(
        new Document("$match",
            new Document("status", "SHIPPED")
        ),
        new Document("$group",
            new Document("_id", "$region")
                .append("revenue", new Document("$sum", "$totalAmount"))
                .append("avgOrder", new Document("$avg", "$totalAmount"))
        ),
        new Document("$sort",
            new Document("revenue", -1)
        ),
        new Document("$limit", 10)
    );

    AggregateIterable<Document> results = collection.aggregate(pipeline)
        .allowDiskUse(true);   // allow spill to disk for large data sets

    List<Document> output = new java.util.ArrayList<>();
    results.into(output);
    return output;
}

