// Run explain in the MongoDB shell (mongosh)
db.orders.find(
  { customerId: "cust_123", status: "SHIPPED" }
).explain("executionStats")

// Key fields to inspect in the output:
// executionStats.executionStages.stage        — should be "IXSCAN", not "COLLSCAN"
// executionStats.totalDocsExamined            — documents scanned by the query
// executionStats.totalDocsReturned            — documents matching the filter
// executionStats.executionTimeMillis          — total wall-clock time
// executionStats.executionStages.inputStage   — drill down to see child stages

// BAD output example (COLLSCAN):
// {
//   "executionStats": {
//     "stage": "COLLSCAN",
//     "totalDocsExamined": 500000,
//     "totalDocsReturned": 12,
//     "executionTimeMillis": 342
//   }
// }

// GOOD output example (IXSCAN after adding index):
// {
//   "executionStats": {
//     "stage": "FETCH",
//     "inputStage": {
//       "stage": "IXSCAN",
//       "keyPattern": { "customerId": 1, "status": 1 }
//     },
//     "totalDocsExamined": 12,
//     "totalDocsReturned": 12,
//     "executionTimeMillis": 1
//   }
// }

// Add the missing compound index:
db.orders.createIndex({ customerId: 1, status: 1 })

// Explain on an aggregation pipeline:
db.orders.explain("executionStats").aggregate([
  { $match: { status: "SHIPPED" } },
  { $group: { _id: "$customerId", total: { $sum: "$amount" } } }
])

