import com.mongodb.ReadPreference;
import com.mongodb.MongoClientSettings;
import com.mongodb.ConnectionString;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.mongodb.core.MongoTemplate;
import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoClients;

@Configuration
public class MongoReadPreferenceConfig {

    // Option 1: Set default read preference on the MongoClient
    @Bean
    public MongoClient mongoClient() {
        MongoClientSettings settings = MongoClientSettings.builder()
            .applyConnectionString(new ConnectionString(
                "mongodb://host1:27017,host2:27017,host3:27017/?replicaSet=rs0"
            ))
            // secondaryPreferred: reads go to a secondary; fallback to primary if none available
            .readPreference(ReadPreference.secondaryPreferred())
            .build();
        return MongoClients.create(settings);
    }
}

// Option 2: Override read preference for a specific query via MongoTemplate
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import com.mongodb.ReadPreference;

// In your service:
public List<Product> readHeavyReport(String category) {
    Query query = new Query(Criteria.where("category").is(category));

    // Read from secondary to offload the primary for this expensive report query
    return mongoTemplate
        .withSession(mongoTemplate.getMongoDbFactory()
            .getSession(com.mongodb.client.ClientSession.class))
        // Note: for per-query override, use MongoDatabase.withReadPreference directly
        // or configure a secondary MongoTemplate bean with secondaryPreferred
        .find(query, Product.class);
}

// Option 3: Define a separate MongoTemplate bean for secondary reads
@Bean(name = "secondaryMongoTemplate")
public MongoTemplate secondaryMongoTemplate(MongoDatabaseFactory factory) {
    MongoTemplate template = new MongoTemplate(factory);
    template.setReadPreference(ReadPreference.secondary());
    return template;
}

